for z0, z1 in sorted({(a, b) for _, _, a, b in P}):   # 층마다: 바깥 고리 - 구멍 고리 면을 그대로 돌출 · 같은 층 조각은 서로 안 겹침
    S = [cq.Solid.extrudeLinear(cq.Face.makeFromWires(W(o, z0), [W(h, z0) for h in hs]), cq.Vector(0, 0, z1 - z0)) for o, hs, a, b in P if (a, b) == (z0, z1)]
    s = cq.Workplane('XY').add(cq.Compound.makeCompound(S))
    r = s if r is None else r.union(s)
